import json, pathlib, sys
from importlib.metadata import distributions
import repropatch
assert repropatch.__version__ == '0.2.0rc1'
location = pathlib.Path(repropatch.__file__).parent
assert location.is_relative_to(sys.prefix)
for path in (pathlib.Path(sys.argv[1]) / 'src/repropatch').glob('*.py'):
    assert path.read_bytes() == (location / path.name).read_bytes(), path
import repropatch.cli, repropatch.reports
assert 'agents' not in sys.modules and 'openai' not in sys.modules and 'repropatch.models' not in sys.modules
packages = {dist.metadata['Name'].lower():dist.version for dist in distributions()}
if sys.argv[2] == 'core':
    assert set(packages) == {'repropatch','pyyaml'}
else:
    for name, version in {'openai-agents':'0.24.0','openai':'3.35.1', 'httpx2':'2.15.1','pydantic':'2.14.1'}.items():
        assert packages[name] == version
print(json.dumps({'location':str(location),'packages':packages,'source_bytes_match':True, 'core_import_without_sdk':True}, indent=2))

